mapper.update:
UPDATE node_info SET state = #{state}
WHERE uuid IN

    #{uuids}

mapper.select:
SELECT a.name,a.host_name,a.ip,a.uuid,a.type,a.tag,a.user_name,a.password,a.state,a.u_size,a.cabinet_start,a.snmp_port,a.snmp_community,a.remark,a.cabinet_id
FROM node_info a

    LEFT JOIN node_cabinet b ON a.cabinet_id = b.id

WHERE a.state != 3

    AND b.room_id = #{params.roomId} AND b.del_flag = 0



    AND a.ip LIKE CONCAT('%', #{params.ip}, '%')



    AND a.name like CONCAT('%', #{params.name}, '%')



    AND a.state = #{params.state}



    AND a.type = #{params.type}



    AND a.tag = #{params.tag}



    AND a.cabinet_id = #{params.cabinetId}

SELECT c.name,c.host_name,c.ip,c.uuid,c.type,c.tag,c.user_name,c.password,c.state,c.u_size,c.cabinet_start,c.snmp_port,c.snmp_community,c.remark,c.cabinet_id FROM
(
    SELECT DISTINCT b.* FROM node_group_rel a
    LEFT JOIN node_info b on a.uuid = b.uuid
    WHERE a.del_flag = 0  AND  a.group_id IN

        #{groupdIds}

) c



    INNER JOIN node_cabinet d ON c.cabinet_id = d.id


WHERE c.state != 3


    AND d.room_id  = #{params.roomId}



    AND c.ip LIKE CONCAT('%', #{params.ip}, '%')



    AND c.name LIKE CONCAT('%', #{params.name}, '%')



    AND c.state = #{params.state}



    AND c.type = #{params.type}



    AND c.tag = #{params.tag}



    AND c.cabinet_id = #{params.cabinetId}
